    fun getSurahForPage(page: Int): Surah? {
        if (page !in 1..604) return null
        return surahs.firstOrNull { it.startPage == page }
            ?: surahs.lastOrNull { it.startPage <= page }
    }

    fun getJuzForPage(page: Int): Juz? {
        if (page !in 1..604) return null
        return juzs.lastOrNull { it.startPage <= page }
    }

    fun getSurahByNumber(number: Int): Surah? {
        return surahs.find { it.number == number }
    }

    fun getJuzByNumber(number: Int): Juz? {
        return juzs.find { it.number == number }
    }
}
